import { Effect, Layer, Stream } from "effect";
import { resultEvents } from "./generation.js";
import { RequestExecutor } from "./route/executor.js";
import { AIError, UnsupportedOperationError } from "./schema/index.js";
/** One modality's layer and service accessors, dispatching each request on its route's `kind`. */
export const make = (service, input) => ({
    layer: Layer.effect(service, Effect.gen(function* () {
        const executor = yield* RequestExecutor.Service;
        const notQueued = (route, operation) => new AIError({
            reason: new UnsupportedOperationError({
                operation: `${input.modality}.${operation}`,
                provider: route.provider,
                route: route.id,
                message: `${route.provider}/${route.id} is not a queued route; use generate or stream`,
            }),
        });
        const start = (request) => {
            const route = request.model.route;
            if (route.kind !== "queued")
                return Effect.fail(notQueued(route, "start"));
            return route.start(request, executor.execute);
        };
        return service.of({
            start,
            resume: (model, token) => {
                if (model.route.kind !== "queued")
                    return Effect.fail(notQueued(model.route, "resume"));
                return model.route.resume(model, token, executor.execute);
            },
            generate: (request, options) => {
                const route = request.model.route;
                if (route.kind !== "queued")
                    return route.generate(request, executor.execute);
                return start(request).pipe(Effect.flatMap((generation) => generation.await(options)));
            },
            stream: (request, options) => {
                const route = request.model.route;
                if (route.kind === "stream")
                    return route.stream(request, executor.execute);
                if (route.kind === "queued")
                    return Stream.unwrap(start(request).pipe(Effect.map((generation) => resultEvents(generation, input.responseEvents, options))));
                return Stream.fromIterableEffect(Effect.map(route.generate(request, executor.execute), input.responseEvents));
            },
        });
    })),
    generate: (request, options) => service.use((client) => client.generate(request, options)),
    stream: (request, options) => Stream.unwrap(service.useSync((client) => client.stream(request, options))),
    start: (request) => service.use((client) => client.start(request)),
    resume: (model, token) => service.use((client) => client.resume(model, token)),
});
export * as MediaClient from "./media-client.js";
